avol (aralash asosdagi sonlarni tartiblash); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":4,"cognitive":"qollash","ref":"m05-qa20261020:adapted:demo2026-sort-5"},{"lesson":2,"format":"Y3","tag":"demo2026-sort-6","stem":"Quyidagi turli asosda berilgan sonlarni o‘sish tartibida joylashtiring (namuna 6).","steps":["D8₍16₎","11010001₍2₎","3131₍4₎","324₍8₎"],"sequence":[1,3,0,2],"explanation":"11010001₍2₎=209₍10₎; D8₍16₎=216₍10₎; 324₍8₎=212₍10₎; 3131₍4₎=221₍10₎. O‘sish: 11010001₍2₎ < 324₍8₎ < D8₍16₎ < 3131₍4₎.","source":"Demo 2026 test 10 000 so`mlik.pdf, PDF 2-sahifa, 4-savol (aralash asosdagi sonlarni tartiblash); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":4,"cognitive":"qollash","ref":"m05-qa20261020:adapted:demo2026-sort-6"},{"lesson":3,"format":"Y3","tag":"pair-sums-sort-1","stem":"Har xil asosda berilgan ifodalarni yig‘indi qiymatining o‘sish tartibida joylashtiring (variant 1).","steps":["151₍8₎ + 10₍8₎","1011110₍2₎ + 111₍2₎","1232₍4₎ + 22₍4₎","63₍16₎ + 9₍16₎"],"sequence":[1,3,0,2],"explanation":"1011110₍2₎ + 111₍2₎ = 94+7=101₍10₎; 151₍8₎ + 10₍8₎ = 105+8=113₍10₎; 63₍16₎ + 9₍16₎ = 99+9=108₍10₎; 1232₍4₎ + 22₍4₎ = 110+10=120₍10₎.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 7-sahifa, 14-savol (yig‘indisi eng katta juftlik); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":5,"cognitive":"mulohaza","ref":"m05-qa20261020:adapted:pair-sums-sort-1"},{"lesson":3,"format":"Y3","tag":"pair-sums-sort-2","stem":"Har xil asosda berilgan ifodalarni yig‘indi qiymatining o‘sish tartibida joylashtiring (variant 2).","steps":["165₍8₎ + 10₍8₎","1101010₍2₎ + 111₍2₎","1322₍4₎ + 22₍4₎","6F₍16₎ + 9₍16₎"],"sequence":[1,3,0,2],"explanation":"1101010₍2₎ + 111₍2₎ = 106+7=113₍10₎; 165₍8₎ + 10₍8₎ = 117+8=125₍10₎; 6F₍16₎ + 9₍16₎ = 111+9=120₍10₎; 1322₍4₎ + 22₍4₎ = 122+10=132₍10₎.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 7-sahifa, 14-savol (yig‘indisi eng katta juftlik); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":5,"cognitive":"mulohaza","ref":"m05-qa20261020:adapted:pair-sums-sort-2"},{"lesson":3,"format":"Y3","tag":"pair-sums-sort-3","stem":"Har xil asosda berilgan ifodalarni yig‘indi qiymatining o‘sish tartibida joylashtiring (variant 3).","steps":["201₍8₎ + 10₍8₎","1110110₍2₎ + 111₍2₎","2012₍4₎ + 22₍4₎","7B₍16₎ + 9₍16₎"],"sequence":[1,3,0,2],"explanation":"1110110₍2₎ + 111₍2₎ = 118+7=125₍10₎; 201₍8₎ + 10₍8₎ = 129+8=137₍10₎; 7B₍16₎ + 9₍16₎ = 123+9=132₍10₎; 2012₍4₎ + 22₍4₎ = 134+10=144₍10₎.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 7-sahifa, 14-savol (yig‘indisi eng katta juftlik); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":5,"cognitive":"mulohaza","ref":"m05-qa20261020:adapted:pair-sums-sort-3"},{"lesson":3,"format":"Y3","tag":"story-solution-1","stem":"Turli sanoq sistemalarida berilgan miqdorlar farqiga oid hayotiy masalani yechishning to‘g‘ri ketma-ketligini aniqlang (variant 1).","steps":["Jami sondan birinchi guruh sonini ayirish","Berilgan jami va birinchi guruh qiymatlarining sanoq asoslarini aniqlash","Hisoblangan farqni masaladagi ikkinchi guruh miqdori sifatida tekshirish","Ikkala qiymatni o‘nlik sanoq sistemasiga o‘tkazish"],"sequence":[1,3,0,2],"explanation":"1. Berilgan jami va birinchi guruh qiymatlarining sanoq asoslarini aniqlash → 2. Ikkala qiymatni o‘nlik sanoq sistemasiga o‘tkazish → 3. Jami sondan birinchi guruh sonini ayirish → 4. Hisoblangan farqni masaladagi ikkinchi guruh miqdori sifatida tekshirish; manba uslubi: 2026-yil attestatsiya 15-savol.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 8-sahifa, 15-savol (kundalik vaziyatda sanoq sistemasi); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":4,"cognitive":"qollash","ref":"m05-qa20261020:adapted:story-solution-1"},{"lesson":3,"format":"Y3","tag":"story-solution-2","stem":"Turli sanoq sistemalarida berilgan miqdorlar farqiga oid hayotiy masalani yechishning to‘g‘ri ketma-ketligini aniqlang (variant 2).","steps":["Ikkinchi miqdorni ayirish bilan topish","O‘n oltilik va sakkizlik sonlar uchun ruxsat etilgan raqamlarni tekshirish","Natijani talab etilgan asosda yozib tekshirish","Jami va ajratilgan miqdorni umumiy sanoq sistemasiga keltirish"],"sequence":[1,3,0,2],"explanation":"1. O‘n oltilik va sakkizlik sonlar uchun ruxsat etilgan raqamlarni tekshirish → 2. Jami va ajratilgan miqdorni umumiy sanoq sistemasiga keltirish → 3. Ikkinchi miqdorni ayirish bilan topish → 4. Natijani talab etilgan asosda yozib tekshirish; manba uslubi: 2026-yil attestatsiya 15-savol.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 8-sahifa, 15-savol (kundalik vaziyatda sanoq sistemasi); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":4,"cognitive":"qollash","ref":"m05-qa20261020:adapted:story-solution-2"},{"lesson":3,"format":"Y3","tag":"story-solution-3","stem":"Turli sanoq sistemalarida berilgan miqdorlar farqiga oid hayotiy masalani yechishning to‘g‘ri ketma-ketligini aniqlang (variant 3).","steps":["Qolgan miqdorni farq orqali aniqlash","Masalada berilgan ikki miqdorning yozuv va asoslarini belgilash","Topilgan natija jami miqdordan oshmaganini tekshirish","Har bir miqdorning haqiqiy o‘nlik qiymatini hisoblash"],"sequence":[1,3,0,2],"explanation":"1. Masalada berilgan ikki miqdorning yozuv va asoslarini belgilash → 2. Har bir miqdorning haqiqiy o‘nlik qiymatini hisoblash → 3. Qolgan miqdorni farq orqali aniqlash → 4. Topilgan natija jami miqdordan oshmaganini tekshirish; manba uslubi: 2026-yil attestatsiya 15-savol.","source":"13.04.2026 Attetasiya Tushgan savollar.pdf, PDF 8-sahifa, 15-savol (kundalik vaziyatda sanoq sistemasi); unga asoslangan yangi variant; 2026 Informatika attestatsiya spetsifikatsiyasi, PDF 3–4; ICT 7-sinf 2021, PDF 9–20","difficulty":4,"cognitive":"qollash","ref":"m05-qa20261020:adapted:story-solution-3"}]'::jsonb;
  q jsonb;
  module_lesson public.lessons%rowtype;
  reference_question public.questions%rowtype;
  qid uuid;
  oid uuid;
  a_ids uuid[];
  b_ids uuid[];
  keymap jsonb;
  keyval jsonb;
  sf text;
  i int;
  j int;
  n int;
  previous int;
  deprecated_count int;
  y1 int;
  y2 int;
  y3 int;
BEGIN
 IF jsonb_array_length(bank)<>30 THEN RAISE EXCEPTION 'M05 QA items must equal 30';END IF;
 SELECT COUNT(*) INTO previous FROM public.questions WHERE source_reference LIKE 'm05-qa20261020:adapted:%';
 IF previous=30 THEN
    RAISE NOTICE 'M05 QA already imported; no new changes';
    RETURN;
 END IF;
 IF previous<>0 THEN RAISE EXCEPTION 'M05 QA partial preexisting batch %',previous; END IF;
 SELECT COUNT(*) FILTER(WHERE q.format='Y1'),COUNT(*) FILTER(WHERE q.format='Y2'),COUNT(*) FILTER(WHERE q.format='Y3')
 INTO y1,y2,y3 FROM public.questions q JOIN public.lessons l ON l.id=q.source_lesson_id
 JOIN public.modules m ON m.id=l.module_id WHERE m.code='M05' AND q.status='published';
 IF y1<>289 OR y2<>50 OR y3<>50 THEN
    RAISE EXCEPTION 'Expected prior M05 289/50/50, saw %/%/%',y1,y2,y3;
 END IF;
 FOR q IN SELECT value FROM jsonb_array_elements(bank) LOOP
   SELECT l.* INTO STRICT module_lesson FROM public.lessons l JOIN public.modules m ON m.id=l.module_id
   WHERE m.code='M05' AND l.order_idx=(q->>'lesson')::int AND l.status='published';
   SELECT sample.* INTO STRICT reference_question FROM public.questions sample JOIN public.constructs c
   ON c.id=sample.construct_id WHERE sample.source_lesson_id=module_lesson.id AND sample.status='published'
    AND c.code=('S3.NUM.0'||(q->>'lesson')) LIMIT 1;
   sf:=q->>'format';
   INSERT INTO public.questions (subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,
      is_generated,status,source_reference,source_lesson_id)
   VALUES(reference_question.subject_id,reference_question.construct_id,reference_question.group_code,
      sf::public.question_format,(q->>'cognitive')::public.cognitive_level,
      (q->>'difficulty')::int,q->>'stem',false,'published'::public.content_status,q->>'ref',module_lesson.id)
   RETURNING id INTO qid;
   a_ids:=ARRAY[]::uuid[];b_ids:=ARRAY[]::uuid[];
   IF sf='Y1' THEN
     IF jsonb_array_length(q->'choices')<>4 THEN RAISE EXCEPTION 'Y1 option count bad'; END IF;
     FOR i IN 0..3 LOOP
        INSERT INTO public.question_options(question_id,side,order_idx,content_md)
        VALUES(qid,'a',i+1,q->'choices'->>i) RETURNING id INTO oid;
        a_ids:=array_append(a_ids,oid);
     END LOOP;
     j:=(q->>'correct')::int+1;
     IF j<1 OR j>4 THEN RAISE EXCEPTION 'Y1 key invalid'; END IF;
     keyval:=jsonb_build_object('correct_option_id',a_ids[j]);
   ELSIF sf='Y2' THEN
     IF jsonb_array_length(q->'left')<>4 OR jsonb_array_length(q->'right')<>4
       OR jsonb_array_length(q->'pairs')<>4 THEN RAISE EXCEPTION 'Y2 option count bad'; END IF;
     FOR i IN 0..3 LOOP
       INSERT INTO public.question_options(question_id,side,order_idx,content_md)
       VALUES(qid,'a',i+1,q->'left'->>i) RETURNING id INTO oid;
       a_ids:=array_append(a_ids,oid);
       INSERT INTO public.question_options(question_id,side,order_idx,content_md)
       VALUES(qid,'b',i+1,q->'right'->>i) RETURNING id INTO oid;
       b_ids:=array_append(b_ids,oid);
     END LOOP;
     keymap:='{}'::jsonb;
     FOR i IN 0..3 LOOP
       j:=(q->'pairs'->>i)::int+1;
       IF j<1 OR j>4 THEN RAISE EXCEPTION 'Y2 mapping invalid';END IF;
       keymap:=keymap||jsonb_build_object(a_ids[i+1]::text,b_ids[j]);
     END LOOP;
     keyval:=jsonb_build_object('pairs',keymap);
   ELSIF sf='Y3' THEN
     IF jsonb_array_length(q->'steps')<>4 OR jsonb_array_length(q->'sequence')<>4 THEN RAISE EXCEPTION 'Y3 option count bad'; END IF;
     FOR i IN 0..3 LOOP
       INSERT INTO public.question_options(question_id,side,order_idx,content_md)
       VALUES(qid,'a',i+1,q->'steps'->>i) RETURNING id INTO oid;
       a_ids:=array_append(a_ids,oid);
     END LOOP;
     keymap:='[]'::jsonb;
     FOR i IN 0..3 LOOP
       j:=(q->'sequence'->>i)::int+1;
       IF j<1 OR j>4 THEN RAISE EXCEPTION 'Y3 index invalid';END IF;
       keymap:=keymap||jsonb_build_array(a_ids[j]);
     END LOOP;
     keyval:=jsonb_build_object('order',keymap);
   ELSE RAISE EXCEPTION 'Unexpected format %',sf;
   END IF;
   INSERT INTO public.question_keys(question_id,payload,explanation_md)
   VALUES(qid,keyval,(q->>'explanation')|| E'\nManbaviy uslub: ' || (q->>'source'));
 END LOOP;
 -- Retire only previously UNSEEN generated-ordering question items;
 -- three questions already in exam_items remain published unchanged.
 UPDATE public.questions oldq SET status='archived'::public.content_status,updated_at=now()
 WHERE oldq.status='published' AND oldq.format='Y3'
  AND oldq.source_reference LIKE 'generated:sanoqSistema:S3.NUM.03:%'
  AND EXISTS (SELECT 1 FROM public.lessons l JOIN public.modules m ON m.id=l.module_id
              WHERE l.id=oldq.source_lesson_id AND m.code='M05')
  AND NOT EXISTS(SELECT 1 FROM public.exam_items ei WHERE ei.question_id=oldq.id);
 GET DIAGNOSTICS deprecated_count=ROW_COUNT;
 IF deprecated_count<>12 THEN RAISE EXCEPTION 'Expected to archive 12 entirely-unused repeated Y3, actually %',deprecated_count; END IF;
 SELECT COUNT(*) FILTER(WHERE q.format='Y1'),COUNT(*) FILTER(WHERE q.format='Y2'),COUNT(*) FILTER(WHERE q.format='Y3')
 INTO y1,y2,y3 FROM public.questions q JOIN public.lessons l ON l.id=q.source_lesson_id
 JOIN public.modules m ON m.id=l.module_id WHERE m.code='M05' AND q.status='published';
 IF y1<>301 OR y2<>56 OR y3<>50 THEN RAISE EXCEPTION 'Expected post M05 301/56/50, saw %/%/%',y1,y2,y3; END IF;
END $m05q$;
COMMIT;
SELECT q.format::text, q.status::text,COUNT(*) n FROM public.questions q
JOIN public.lessons l ON l.id=q.source_lesson_id JOIN public.modules m ON m.id=l.module_id
WHERE m.code='M05' GROUP BY q.format,q.status ORDER BY q.format,q.status;
